package cursor

import (
	"fmt"
	"io"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// HookNames returns the hook verbs Cursor supports.
// Delegates to GetHookNames for backward compatibility.
func (c *CursorAgent) HookNames() []string {
	return c.GetHookNames()
}

// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance.
func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		return c.parseSessionStart(stdin)
	case HookNameBeforeSubmitPrompt:
		return c.parseTurnStart(stdin)
	case HookNameStop:
		return c.parseTurnEnd(stdin)
	case HookNameSessionEnd:
		return c.parseSessionEnd(stdin)
	case HookNamePreCompact:
		return c.parsePreCompact(stdin)
	case HookNameSubagentStart:
		return c.parseSubagentStart(stdin)
	case HookNameSubagentStop:
		return c.parseSubagentStop(stdin)
	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (c *CursorAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// Note: CursorAgent does NOT implement TranscriptAnalyzer. Cursor's transcript
// format does not contain tool_use blocks that would allow extracting modified
// files. File detection relies on git status instead.

// --- Internal hook parsing functions ---

func (c *CursorAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[beforeSubmitPromptInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Prompt:     raw.Prompt,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parseTurnEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parseSessionEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionEnd,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parsePreCompact(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[preCompactHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.Compaction,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentStartHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	if raw.Task == "" {
		return nil, nil
	}
	return &agent.Event{
		Type:       agent.SubagentStart,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		ToolUseID:  raw.SubagentId,
		//TODO ToolInput:  raw.Task,
		Timestamp: time.Now(),
	}, nil
}

func (c *CursorAgent) parseSubagentStop(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentStopHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	if raw.Task == "" {
		return nil, nil
	}
	event := &agent.Event{
		Type:       agent.SubagentEnd,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		ToolUseID:  raw.SubagentId,
		//TODO ToolInput:  raw.Task,
		Timestamp: time.Now(),
	}
	if raw.SubagentId != "" {
		event.SubagentID = raw.SubagentId
	}
	return event, nil
}

package cursor

import "encoding/json"

// CursorHooksFile represents the .cursor/HooksFileName structure.
// Cursor uses a flat JSON file with version and hooks sections.
//
//nolint:revive // CursorHooksFile is clearer than HooksFile when used outside this package
type CursorHooksFile struct {
	Version int         `json:"version"`
	Hooks   CursorHooks `json:"hooks"`
}

// CursorHooks contains all hook configurations using camelCase keys.
//
//nolint:revive // CursorHooks is clearer than Hooks when used outside this package
type CursorHooks struct {
	SessionStart       []CursorHookEntry `json:"sessionStart,omitempty"`
	SessionEnd         []CursorHookEntry `json:"sessionEnd,omitempty"`
	BeforeSubmitPrompt []CursorHookEntry `json:"beforeSubmitPrompt,omitempty"`
	Stop               []CursorHookEntry `json:"stop,omitempty"`
	PreCompact         []CursorHookEntry `json:"preCompact,omitempty"`
	SubagentStart      []CursorHookEntry `json:"subagentStart,omitempty"`
	SubagentStop       []CursorHookEntry `json:"subagentStop,omitempty"`
}

// CursorHookEntry represents a single hook command.
// Cursor hooks have a command string and an optional matcher field for filtering by tool name.
//
//nolint:revive // CursorHookEntry is clearer than HookEntry when used outside this package
type CursorHookEntry struct {
	Command string `json:"command"`
	Matcher string `json:"matcher,omitempty"`
}

// sessionInfoRaw is the JSON structure from SessionStart/SessionEnd/Stop hooks.
// Cursor may provide session_id or conversation_id (fallback).
type sessionInfoRaw struct {
	// common
	ConversationID string   `json:"conversation_id"`
	GenerationID   string   `json:"generation_id"`
	Model          string   `json:"model"`
	HookEventName  string   `json:"hook_event_name"`
	CursorVersion  string   `json:"cursor_version"`
	WorkspaceRoots []string `json:"workspace_roots"`
	UserEmail      string   `json:"user_email"`
	TranscriptPath string   `json:"transcript_path"`
}

// beforeSubmitPromptInputRaw is the JSON structure from BeforeSubmitPrompt hooks.
type beforeSubmitPromptInputRaw struct {
	// common
	ConversationID string   `json:"conversation_id"`
	GenerationID   string   `json:"generation_id"`
	Model          string   `json:"model"`
	HookEventName  string   `json:"hook_event_name"`
	CursorVersion  string   `json:"cursor_version"`
	WorkspaceRoots []string `json:"workspace_roots"`
	UserEmail      string   `json:"user_email"`
	TranscriptPath string   `json:"transcript_path"`

	// hook specific
	Prompt string `json:"prompt"`
}

// preCompactHookInputRaw is the JSON structure from PreCompact hook.
type preCompactHookInputRaw struct {
	// common
	ConversationID string   `json:"conversation_id"`
	GenerationID   string   `json:"generation_id"`
	Model          string   `json:"model"`
	HookEventName  string   `json:"hook_event_name"`
	CursorVersion  string   `json:"cursor_version"`
	WorkspaceRoots []string `json:"workspace_roots"`
	UserEmail      string   `json:"user_email"`
	TranscriptPath string   `json:"transcript_path"`

	// hook specific
	Trigger             string      `json:"trigger"`               // "auto" | "manual",
	ContextUsagePercent json.Number `json:"context_usage_percent"` //: 85,
	ContextTokens       json.Number `json:"context_tokens"`        // 120000,
	ContextWindowSize   json.Number `json:"context_window_size"`   //: 128000,
	MessageCount        json.Number `json:"message_count"`         // 45,
	MessagesToCompact   json.Number `json:"messages_to_compact"`   //: 30,
	IsFirstCompaction   bool        `json:"is_first_compaction"`   // true | false
}

// subagentStartHookInputRaw is the JSON structure from SubagentStart[Task] hook.
type subagentStartHookInputRaw struct {
	// common
	ConversationID string   `json:"conversation_id"`
	GenerationID   string   `json:"generation_id"`
	Model          string   `json:"model"`
	HookEventName  string   `json:"hook_event_name"`
	CursorVersion  string   `json:"cursor_version"`
	WorkspaceRoots []string `json:"workspace_roots"`
	UserEmail      string   `json:"user_email"`
	TranscriptPath string   `json:"transcript_path"`

	// hook specific
	SubagentId           string `json:"subagent_id"`
	SubagentType         string `json:"subagent_type"`
	SubagentModel        string `json:"subagent_model"`
	Task                 string `json:"task"`
	ParentConversationID string `json:"parent_conversation_id"`
	ToolCallID           string `json:"tool_call_id"`
	IsParallelWorker     bool   `json:"is_parallel_worker"`
}

// subagentStopHookInputRaw is the JSON structure from SubagentStop hooks.
type subagentStopHookInputRaw struct {
	// common
	ConversationID string   `json:"conversation_id"`
	GenerationID   string   `json:"generation_id"`
	Model          string   `json:"model"`
	HookEventName  string   `json:"hook_event_name"`
	CursorVersion  string   `json:"cursor_version"`
	WorkspaceRoots []string `json:"workspace_roots"`
	UserEmail      string   `json:"user_email"`
	TranscriptPath string   `json:"transcript_path"`

	// hook specific
	SubagentId           string      `json:"subagent_id"`
	SubagentType         string      `json:"subagent_type"`
	Status               string      `json:"status"`
	Duration             json.Number `json:"duration_ms"`
	Summary              string      `json:"summary"`
	ParentConversationID string      `json:"parent_conversation_id"`
	MessageCount         json.Number `json:"message_count"`
	ToolCallCount        json.Number `json:"tool_call_count"`
	ModifiedFiles        []string    `json:"modified_files"`
	LoopCount            json.Number `json:"loop_count"`
	Task                 string      `json:"task"`
	Description          string      `json:"description"`
	AgentTranscriptPath  string      `json:"agent_transcript_path"`
}

