	if err != nil {
		t.Fatalf("ReadTranscript() error = %v", err)
	}

	// ReadSession
	session, err := ag.ReadSession(&agent.HookInput{
		SessionID:  "compare-session",
		SessionRef: transcriptPath,
	})
	if err != nil {
