	if path == "" {
		return &agent.TokenUsage{}, nil
	}

	lines, _, err := transcript.ParseFromFileAtLine(path, startLine)
	if err != nil {
		return nil, err //nolint:wrapcheck // caller adds context
	}

	return calculateTokenUsage(lines), nil

