// calculateTokenUsage calculates token usage from raw transcript data.
// startOffset is the line number (Claude Code) or message index (Gemini CLI)
// where the current checkpoint began, allowing calculation for only the portion
// of the transcript since the last checkpoint.
//
// The TokenCalculator interface expects a file path, so we write the data
// to a temporary file when no file path is available.
func calculateTokenUsage(agentType agent.AgentType, data []byte, startOffset int) (*agent.TokenUsage, error) {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, err
	}
	tc, ok := ag.(agent.TokenCalculator)
	if !ok {
		return nil, nil
	}

	// Write data to a temp file since the interface expects a file path.
	tmpFile, err := os.CreateTemp("", "entire-transcript-*")
	if err != nil {
		return nil, fmt.Errorf("failed to create temp file for token calculation: %w", err)
	}
	defer os.Remove(tmpFile.Name())

	if _, err := tmpFile.Write(data); err != nil {
		tmpFile.Close()
		return nil, fmt.Errorf("failed to write temp transcript: %w", err)
	}
	tmpFile.Close()

	return tc.CalculateTokenUsage(tmpFile.Name(), startOffset)
}

