func calculateTokenUsage(agentType agent.AgentType, data []byte, startOffset int) (*agent.TokenUsage, error) {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, fmt.Errorf("failed to get agent for token calculation: %w", err)
	}
	tc, ok := ag.(agent.TokenCalculator)
	if !ok {
		return nil, nil //nolint:nilnil // nil usage for agents without token calculation is expected
	}

	// Write data to a temp file since the interface expects a file path.
	tmpFile, err := os.CreateTemp("", "entire-transcript-*")
	if err != nil {
		return nil, fmt.Errorf("failed to create temp file for token calculation: %w", err)
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	_, writeErr := tmpFile.Write(data)
	if closeErr := tmpFile.Close(); closeErr != nil && writeErr == nil {
		writeErr = closeErr
	}
	if writeErr != nil {
		return nil, fmt.Errorf("failed to write temp transcript: %w", writeErr)
	}

	usage, err := tc.CalculateTokenUsage(tmpPath, startOffset)
	if err != nil {
		return nil, fmt.Errorf("failed to calculate token usage: %w", err)
	}

